// v5 manuscript: newly authored sections. Every number below is read from
// results.json (generated by make_results.py); none is typed by hand.

const path = require("path");
const fs = require("fs");
const RES = require(path.join(__dirname, "results.json"));
const M4 = RES.models["gpt-4o-mini"];
const M6 = RES.models["gpt-6-astra"];
const W4 = RES.wording["gpt-4o-mini"];
const W6 = RES.wording["gpt-6-astra"];
const C4 = M4.conditions, C6 = M6.conditions;
const F4 = (RES.followup || {})["gpt-4o-mini"] || {};
const F6 = (RES.followup || {})["gpt-6-astra"] || {};
const FN4 = F4.levels ? F4.levels.X3_note_neutral : null;
const FG4 = F4.levels ? F4.levels.G_gate_only : null;
const fpair = (F, a, b) => (F.pairs || []).find(p => p.a === a && p.b === b);
const FN6 = F6.levels ? F6.levels.X3_note_neutral : null;
const FG6 = F6.levels ? F6.levels.G_gate_only : null;

const pc = (x, d = 1) => (x === null || x === undefined || x !== x) ? "n/a" : (x * 100).toFixed(d);
const pp = (x, d = 1) => (x === null || x === undefined) ? "n/a" : ((x * 100 >= 0 ? "+" : "−") + Math.abs(x * 100).toFixed(d));
const ci = (t) => `[${pc(t[0], 0)}–${pc(t[1], 0)}]`;
const pv = (p) => p < 0.0005 ? "<0.001" : p.toFixed(3);
const nm = (x) => x.toFixed(0);
const relred = (a, b) => pc((a - b) / a, 0);
const peq = (p) => p < 0.0005 ? "p < 0.001" : `p = ${p.toFixed(3)}`;
const jci = (t) => `[${(t.youden_ci[0]*100).toFixed(0)},${(t.youden_ci[1]*100).toFixed(0)}]`.replace(/-/g, "−");

const TITLE = "Provenance Marking and Information Exclusion in LLM-Augmented Alert Triage: Security Effects and Operational Costs";

const authorsBlock = [
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 200 }, children: [R(TITLE, { size: 44 })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [R("Angelin Lipika Edwin Jose Jebaslin Vijila and Chol Hyun Park", { size: 22 })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [R("Department of Computer Science", { size: 20, italics: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, children: [R("University of the Ozarks, Clarksville, AR, USA", { size: 20, italics: true })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 360 }, children: [R("{alipi418, cpark}@ozarks.edu", { size: 20 })] }),
];

const abstractPara = new Paragraph({
  alignment: AlignmentType.JUSTIFIED, spacing: { after: 120 },
  children: [
    R("Abstract—", { size: 18, bold: true, italics: true }),
    R(`Security operations centers increasingly route intrusion-detection alerts through large language models for triage, and much of an alert's text is written by the party under investigation. We evaluate two prompt-level responses — provenance-aware rendering, which labels attacker-writable fields and relocates them to a referenced appendix, and an asymmetric downgrade gate, which re-verifies benign verdicts from sensor-generated fields only — against baselines with explicit reference conditions, on alerts generated in three strata, on two models. The injected miss rate on malicious alerts and the over-escalation rate on benign alerts are pre-specified as a co-primary pair, with exact McNemar tests paired on the same alert. On gpt-4o-mini, provenance rendering cuts the injected miss rate from ${pc(C4.B0_naive.injected_miss)}% to ${pc(C4.P1_pag_render.injected_miss)}% and raises over-escalation from ${pc(C4.B0_naive.oer)}% to ${pc(C4.P1_pag_render.oer)}%; the clean-task Youden's J point estimate falls from ${pp(C4.B0_naive.youden_j)} to ${pp(C4.P1_pag_render.youden_j)} (95% interval ${jci(C4.P1_pag_render)}). Adding the gate reaches zero misses by escalating every alert. No advantage of appendix relocation over inline labeling was demonstrated. On a frontier model the corpus flips no verdict, yet the same prompts raise over-escalation from ${pc(C6.B0_naive.oer)}% to ${pc(C6.P1_pag_render.oer)}–${pc(C6.P2_pag_full.oer)}%. Post hoc, a neutral rewording of the same layout lowers over-escalation on the small model by ${pp(W4.levels.X2_note_authority.oer - FN4.oer, 0).replace('+','')} points relative to the authority-denial level L1 (${pc(W4.levels.X2_note_authority.oer)}% to ${pc(FN4.oer)}%), to a level not distinguishable from the structured baseline at this sample size, while on the frontier model it leaves the cost above the baseline; and the gate applied to every alert accepts no downgrade on either model. On this benchmark the defenses moved the operating point toward escalation; whether they improved discrimination could not be shown, and the cost appeared on both models while attack success from this corpus was observed on one.`, { size: 18, bold: true }),
  ],
});

const indexTerms = new Paragraph({
  alignment: AlignmentType.JUSTIFIED, spacing: { after: 200 },
  children: [R("Index Terms—", { size: 18, bold: true, italics: true }),
             R("prompt injection, large language models, security operations center, alert triage, provenance, alert fatigue, evaluation methodology", { size: 18, bold: true })],
});

const intro = [
  H1("Introduction"),
  body("Large language models are deployed as first-line analysts in security operations. Tooling presents an LLM with an intrusion-detection alert and asks whether the event is a genuine attack and whether to escalate, monitor, or close. The motivation is volume: practitioners in interview studies of SOC practice describe false-positive rates as high as 99% and identify volume, not analytic difficulty, as the dominant source of analyst burnout [14], [13].", { noIndent: true }),
  body("These pipelines contain a structural hazard. Alerts are not written by the defender. Much of their content originates in traffic the attacker generated: the HTTP User-Agent header, the request path, attempted usernames, and the log line the sensor preserved. Serializing such an alert into a prompt gives the attacker a channel to the analyst's reasoning requiring no privilege beyond sending traffic to a public service. This is *indirect prompt injection* [1], in which adversarial text reaches the model through data it is asked to process."),
  body("Two 2026 studies establish exploitability. Pandey and Bhujang [11] report that adversarial strings in log fields cause a gpt-4o-mini pipeline to misclassify malicious events as benign in 21% of classification cases without defense, falling to 8% under structured prompting. Landauer et al. [12] show that a sentence framing an intrusion as a controlled testing event shifts verdicts across four model families. Both find imperative overrides ineffective: explicit \"ignore previous instructions\" payloads achieve 0% success in classification [11]. What survives resembles context — a change-ticket number, a named security lead, an approved engagement window."),
  body("We take up two questions these studies leave open. *Which component of a mitigation is responsible for its effect?* Existing defenses bundle delimiters, warnings, keyword filtering, output templating, and input normalization; when a bundle improves on a baseline, the literature does not say which part did the work. *What does the mitigation cost?* A defense that reduces attack success by making the model suspicious of all attacker-written text will also escalate benign alerts, reproducing the fatigue such systems were adopted to relieve. Prior work includes benign cases as a guard against defenses that label everything malicious [11] but does not report the benign false-positive rate as a result; here it is a co-primary quantity, and it turns out to be the decisive one."),
  body("We study two interventions and state what each does and does not provide. *Provenance-aware rendering* assigns trust tiers by schema, normalizes attacker-writable values, and relocates them to a referenced appendix. It belongs to the prompt-level family exemplified by spotlighting [6]; the strings still enter the reasoning context, so it offers no information-flow guarantee. *An asymmetric downgrade gate* re-verifies benign verdicts in a second call receiving trusted fields only. That call does exclude attacker text, but it is invoked on the basis of a first-stage verdict the attacker may already have influenced, and it cannot recover information the exclusion removed."),
  body("The evaluation is built so that the cost can be measured where it arises. Baselines are defined by explicit reference conditions, so that normalization, provenance wording, and appendix rendering are separately estimable. Alerts are generated in three strata — trusted-sufficient, parse-required, and record-required — because exclusion should help where trusted fields suffice and cost utility where they do not. The injected miss rate on malicious alerts and the over-escalation rate on benign alerts are pre-specified as a co-primary pair, and every condition comparison is paired on the same alert."),
  body(`The result is not the one the design was built to confirm. On gpt-4o-mini the proposed rendering does reduce the injected miss rate, from ${pc(C4.B0_naive.injected_miss)}% to ${pc(C4.P1_pag_render.injected_miss)}%, and the reduction is significant. But it escalates ${pc(C4.P1_pag_render.oer)}% of benign alerts, against ${pc(C4.B0_naive.oer)}% for the unprotected baseline, and its clean-task balanced accuracy falls to ${pc(C4.P1_pag_render.balanced_acc)}%. Read on the security metric alone it is a working defense; read on the pair it is a classifier whose attack-free J point estimate is ${pp(C4.P1_pag_render.youden_j)}, with an interval ${jci(C4.P1_pag_render)} that includes zero. The gate completes the movement: it reaches zero misses by escalating every alert. On a frontier model the injection corpus does nothing at all, and the same prompts still raise over-escalation by ${pp(C6.P1_pag_render.oer - C6.B0_naive.oer, 0)} to ${pp(C6.P2_pag_full.oer - C6.B0_naive.oer, 0)} points.`),
  body("Contributions. (1) A component-level evaluation of provenance marking and information exclusion in which each mechanism's guarantee is stated at the strength it supports, with explicit reference conditions and a three-stratum generator whose record-required stratum makes benign verdicts checkable. (2) The finding that, on this benchmark, the behavior of prompt-level provenance marking is consistent with a shift of the operating point rather than an improvement in discrimination: on the small model each strengthening of the provenance note lowers misses and raises over-escalation together, and under the full note the model's clean-task J interval includes zero; no advantage of relocating attacker text to an appendix over labeling it in place was demonstrated; a neutral rewording of the same layout lowered both the cost and the benefit on the small model, to levels not distinguishable from the structured baseline, but left the cost above the baseline on the frontier model; and the downgrade gate accepted no downgrade, neither on the 40 it was asked to verify nor on any judgment when applied to every alert on either model. (3) A cross-model contrast in which attack success from this corpus was observed on one model and the cost on both. (4) Two protocol requirements for this class of evaluation, with pilot evidence. (5) Released generator, delivery-annotated payload corpus, harness, and per-item outputs (https://github.com/chpark0714/pag-alert-triage, release v1.0; MANIFEST.json and prompts.json in the release record model identifiers, run dates, decoding settings, and verbatim prompts)."),
];

const related = [
  H1("Background and Related Work"),
  H2("Indirect Prompt Injection"),
  body("Perez and Ribeiro [2] introduced goal hijacking and prompt leaking through adversarial text in the user turn. Greshake et al. [1] generalized to the indirect setting, where an application retrieving web pages, emails, or documents is compromised by content the attacker planted there. Liu et al. [3] systematized black-box injection against deployed applications and found 31 of 36 commercial applications vulnerable. Prompt injection has held first position in the OWASP Top 10 for LLM Applications through the 2025 revision [4]. The telemetry setting is an instance in which the retrieval channel is the security sensor and the document is the alert.", { noIndent: true }),
  H2("Defense Families and Where Our Methods Sit"),
  body("*Prompt-level* defenses mark or isolate untrusted content through delimiting, datamarking, or encoding; Hines et al. [6] formalize this as spotlighting and report that persistently marking provenance through input transformation reduces attack success from above 50% to below 2% on summarization and question-answering tasks, with the encoding variant depending on model capacity. *Training-level* defenses teach the model to rank channels: Chen et al. [7] fine-tune on structured queries separating instruction from data, reducing the tested manual attacks below 2% while their own adaptive analysis retains nonzero success, and Wallace et al. [8] train an instruction hierarchy, improving in-domain robustness by up to 63% and reporting over-refusal regressions in which the model ignores benign lower-priority instructions. *Architectural* defenses remove the model's ability to act on untrusted text by construction: CaMeL [9] separates a privileged planner from a quarantined model with explicit control- and data-flow and capability-based policies on tool calls, solving 77% of AgentDojo tasks against 84% for the undefended system.", { noIndent: true }),
  body("Two features of this literature bear on our design. Each family reports its security gain on generic summarization, question-answering, or agent tasks, none on security data. And where a utility cost is reported at all — CaMeL's seven-point task loss, the instruction hierarchy's over-refusals — it appears as a secondary quantity rather than paired with the security effect on the same inputs. Spotlighting, the family our rendering belongs to, reports no false-positive metric."),
  body("Our provenance-aware rendering belongs to the first family. It transforms input to mark provenance persistently, as spotlighting does, and constructs no information-flow boundary: the attacker's string is present in the context in which the verdict is formed. What we add within that family is a SOC-specific provenance model — trust tiers assigned by alert field name rather than a single trusted/untrusted split — and a rendering that relocates values to a referenced appendix. Whether that rendering outperforms marking values in place is an empirical question; the pre-specified test is reported in Section VII-B."),
  body("Our downgrade gate withholds input and so resembles the third family, but it is far weaker than CaMeL: it governs one verification stage rather than the control flow, and it neither restricts tool use nor tracks data flow across steps."),
  body("AgentDojo [5] — 97 agent tasks and 629 security cases — is among the few benchmarks reporting task utility alongside attack success, and finds no defense that achieves both high utility and low attack success. Wang et al. [10] review 78 papers, taxonomize defenses by intervention stage, and introduce AgentPI, a benchmark for *context-dependent* tasks in which the agent must legitimately act on information observed in its environment. Their central finding is close to ours: many defenses appear effective on existing benchmarks by suppressing contextual input, yet fail where context-dependent reasoning is essential, and no approach simultaneously achieves high trustworthiness, high utility, and low latency. Alert triage is context-dependent in exactly this sense — the attacker-writable fields are also where a benign alert explains itself — and our record-required stratum is built to make that dependence checkable. What we add to [10] is a domain in which the utility cost has a specific operational name, over-escalation, and a design that measures it on the same alerts as the security effect."),
  H2("LLM-Augmented Security Operations"),
  body("Ndichu et al. [13] survey 87 core studies of LLM and agent use for alert screening and incident summarization, framing alert fatigue as the primary motivation, and list adversarial injection through log entries and retrieved documents as an open direction (their R8) that the surveyed screening literature has not evaluated empirically. Alahmadi et al. [14] find through interviews with 21 SOC practitioners that analysts adopt blanket suppression and severity-skimming heuristics under alert volume and that tool trust is fragile; the 99% figure in their title is a participant's characterization of the false-positive rate, not a measurement. These motivate treating over-escalation as a first-class cost: a defense that escalates benign alerts adds to the burden that produced those heuristics.", { noIndent: true }),
  H2("Telemetry-Borne Injection"),
  body("Pandey and Bhujang [11] first evaluate log-borne injection systematically, defining a remote-attacker threat model, a four-class payload taxonomy (S1 direct override, S2 persona hijack, S3 context manipulation, S4 obfuscated payload), and four defense modes on synthetic logs derived from CIC-IDS2017 [15] and UNSW-NB15 [16] schemas across three tasks: 48 conditions of 200 logs each, 120 malicious and 80 benign, on gpt-4o-mini. Their per-class results reverse older intuitions. Direct override achieves 0% in classification and obfuscated payloads fail entirely, whereas persona hijack suppresses 68% of malicious classifications under the naive prompt and remains effective under the stronger defenses; summarization is their highest-risk task, where context manipulation reaches 96% undefended and 38% under constrained output. Their headline figures are averages across classification, summarization, and remediation. Because our study concerns classification alone, the relevant reference points are their per-task classification figures (Table I), under which structured prompting is the strongest mode and the constrained mode is structured prompting plus output templating rather than a cumulative stack. We adopt both readings in defining our baselines. Their 80 benign logs per condition serve as a guard against defenses that label everything malicious; the escalation rate under each defense is not reported.", { noIndent: true }),
  body("Landauer et al. [12] evaluate benign-framing injections on real labeled traces (AIT-LDS v2 and CAM-LDS), inserted through User-Agent and shell-wrapped command fields, with three generation strategies of increasing attacker knowledge across four model families (GPT-5.2, Qwen-3.5, Llama-3.3, Devstral-2). Attack-specific enriched injections are strongest, reaching 86.7% success on the most susceptible models, and for every attack case some model–injection pair achieves complete evasion. They observe that the model's explanation often acknowledges the injected text as manipulative while the verdict remains benign, and propose inspecting explanations as a detection signal; whether that signal survives a defense that already makes the model suspicious of all attacker text is a question our over-escalation results bear on."),
  body("Relative to [11] and [12], then, three things are open. Neither reports the benign-alert outcome of a defense as a result; neither separates injection-attributable failures from baseline error; and neither constrains payloads to placements the attacker can achieve through a stated delivery path. We take [11] as the closest prior work in threat model and baseline design and claim no priority in the setting. What we add is the joint measurement, and, as Section VII reports, it is the joint measurement that changes the reading of the security result."),
  spacer(40),
  caption("TABLE I. ", "Per-task injection success in prior work [11]. Our study is classification-only; cross-task averages are shown for contrast."),
  tbl(["Defense", "Class.", "Summ.", "Remed.", "Avg."], [
    ["Naive", "0.21", "0.38", "0.21", "0.266"],
    ["Structured", "0.08", "0.31", "0.13", "0.173"],
    ["Sanitized", "0.11", "0.19", "0.09", "0.132"],
    ["Constrained", "0.12", "0.16", "0.08", "0.118"],
  ], [1560, 880, 880, 880, 840]),
  spacer(120),
];

const threat = [
  H1("Threat Model and Delivery"),
  H2("Attacker Capability"),
  body("The attacker is remote, holds no credentials, and can send traffic to publicly reachable services monitored by an IDS. They know an LLM processes alerts downstream but not the prompt template. Their goal is a benign verdict, a no-action recommendation, or omission from a summary. The LLM cannot execute commands or alter SIEM state.", { noIndent: true }),
  body("We state the capability narrowly. The attacker *preserves the observable behavior of the original attack and inserts additional text into specific string fields*. We do not claim attackers cannot influence sensor-generated evidence: connection counts, transfer volumes, timing, and which rule fires are all partly under their control through how the attack is conducted. What they cannot do, while still carrying out the attack, is author the content of infrastructure measurements. That narrower asymmetry is what the methods rely on."),
  H2("Trust Tiers"),
  body("Fields are assigned a tier by name. T0 fields are generated by the sensor or by trusted inventory systems; T1 are measured by infrastructure but not authorable as text; T2 carry strings written by whoever sent the traffic. Unknown fields default to T2. Assignment is by schema rather than content, so the attacker cannot change a field's tier by what they write. This presumes the field names come from a trusted sensor pipeline: a key named \"signature\" inside an attacker-supplied JSON document is not a T0 field, and a deployment that ingests such documents must establish that provenance separately.", { noIndent: true }),
  H2("Delivery Path"),
  body("Prior work places payloads in attacker-controlled fields without stating how the payload reaches the field. We model the path explicitly as transmission followed by sensor encoding:", { noIndent: true }),
  body("attacker input → [transmission constraints] → [sensor encoding] → alert field → [defense rendering] → model.", { noIndent: true, align: AlignmentType.CENTER }),
  body("*Transmission constraints* are per-field limits on character set, length, newline admissibility, and non-ASCII admissibility. We distinguish their basis. Some are protocol-level: an HTTP header cannot contain a bare CRLF without terminating the header, and a request target cannot contain a raw space. Others are application-level conventions. In particular, we apply a letter-digit-hyphen restriction to DNS query names and TLS server names, but this is not a protocol prohibition: RFC 2181 §11 states that any binary string may be used as a DNS label and that implementations must not restrict labels, while noting that applications consuming DNS data may impose their own restrictions [20]. Our rule therefore models typical resolver and sensor validation, and the correct claim is that *the input-validation rule we implement excludes these placements*, not that DNS cannot carry them. We report the two field groups separately rather than pooling them.", { noIndent: true }),
  body("Auditing the 60-payload corpus against ten fields yields 600 (field, payload) combinations, of which 319 are deliverable under our rules and 281 (46.8%) are excluded. Excluding process command lines from the primary threat model — writing one presupposes code execution — leaves 540 combinations in the experiment proper, of which 281 are deliverable and 259 (48.0%) excluded. Placements in DNS query names and TLS server names are excluded entirely by the application-level rule above; request targets admit four. All counts in Table II and in this paragraph are emitted by a single script from the corpus and the field specifications."),
  body("*Sensor encoding and consumption* is the step prior work omits. A preserved raw log line is not a free attacker channel; it is the output of the sensor's parsing and serialization, and what the model finally receives depends on how the consumer reads that output. Contemporary sensors emit JSON, in which a newline is written as the two-character escape sequence defined in RFC 8259 [21]. That escape *represents* a newline; it does not delete one. Three consumption paths therefore differ:"),
  body("*raw* — bytes preserved end to end; *parse* — JSON stored, then deserialized so the field value carries a real newline into the prompt; *serialize* — the serialized log text is pasted into the prompt, so the escape sequence reaches the model as two characters.", { noIndent: true }),
  body("We take *parse* as the default, since deserializing a log record before templating it into a prompt is the common integration. Under it, a newline written by the attacker reaches the model as a newline. The *serialize* path is the one in which the escape survives as two characters, and *raw* is a byte-preserving control. We do not describe any path as an upper bound on attack success: monotonicity is not guaranteed, since an escaped representation is not obviously less persuasive than a literal one.", { noIndent: true }),
  body("Accordingly we keep three claims separate: that a payload is not byte-identical after the round trip; that its newline placement changed; and that it failed to move the model's verdict. The first two are preprocessing diagnostics recorded per item, including the exact string placed in the request content. Only the third is an attack outcome, and it is measured from final verdicts alone."),
  spacer(40),
  caption("TABLE II. ", "Deliverable payloads per field (of 15 per class), before sensor encoding. Basis: P = protocol, A = application convention. Generated from the corpus by script."),
  tbl(["Field", "Basis", "S1", "S2", "S3", "S4"], [
    ["user_agent", "P", "14", "13", "1", "10"],
    ["referer", "P", "14", "13", "1", "10"],
    ["uri", "P", "0", "0", "0", "4"],
    ["http_body", "P", "15", "15", "15", "15"],
    ["username", "A", "14", "13", "1", "10"],
    ["filename", "A", "14", "15", "0", "14"],
    ["dns_query", "A", "0", "0", "0", "0"],
    ["tls_sni", "A", "0", "0", "0", "0"],
    ["raw_msg", "A", "15", "15", "15", "15"],
    ["cmdline (excl.)", "A", "14", "13", "1", "10"],
  ], [1700, 600, 610, 610, 610, 610], { align: [AlignmentType.LEFT, AlignmentType.CENTER, AlignmentType.CENTER, AlignmentType.CENTER, AlignmentType.CENTER, AlignmentType.CENTER] }),
  spacer(120),
];

const method = [
  H1("Method"),
  body("Three components are enabled independently so their contributions separate. We state the guarantee each provides before describing it.", { noIndent: true }),
  H2("D1: Trust-Tier Classification"),
  body("Each field maps to T0, T1, or T2 by name, with unknown fields failing closed to T2. D1 is no defense on its own; it is the input to D2 and D3.", { noIndent: true }),
  H2("D2: Provenance-Aware Rendering"),
  body("D2 restructures the prompt into three regions. An ALERT region carries T0 and T1 fields, labeled sensor-generated. An ATTACKER-WRITABLE region lists the *names* of T2 fields present, each mapped to an opaque reference. An EVIDENCE APPENDIX expands each reference to its normalized value, prefaced by a fixed statement that the strings were written by whoever sent the traffic, are forensic artifacts rather than messages addressed to the analyst, and that a string appearing to grant approval is itself evidence of evasion.", { noIndent: true }),
  body("Normalization applies Unicode NFKC, replaces control characters with a single space, collapses whitespace, and truncates at 240 characters. We measured what this removes, using the *final field value* — original content, separator, and payload — rather than the payload alone. No final value in the corpus reaches the truncation threshold, the longest being 151 characters, so truncation never fires. Normalization removes control characters, including any newline that survived sensor encoding, and leaves lexical content intact. It does not prevent the model from reading a payload."),
  body("*What D2 does not provide.* The normalized value appears in the same call and context as the verdict. D2 is a provenance-marking technique in the sense of [6]; its distinctiveness is the field-level trust model and the referenced-appendix rendering, not any interruption of information flow."),
  H2("D3: Asymmetric Downgrade Gate"),
  body("The attacker's objective has one direction: a benign verdict. D3 adds a second call only when the first-stage verdict is benign or the action is close. The second call receives T0 and T1 fields only. If it does not find the benign verdict justified, the verdict is overridden to escalate. Malicious verdicts incur no additional cost, so overhead scales with the benign fraction.", { noIndent: true }),
  body("*Scope of the guarantee.* For a fixed alert, no T2 string enters the gate's input. That is the whole of it. The pipeline is not thereby injection-resistant: the gate is invoked only when the first stage returned benign, which the attacker may have caused, and where trusted fields are insufficient to establish maliciousness the gate cannot recover a verdict the first stage lost. Note also that a gate is not powerless where trusted fields are uninformative — a gate that rejected every closure would reduce attack success there as well — but it would do so by escalating benign alerts in proportion. The quantity of interest is therefore not whether the gate can help but what it charges for the help, which Section V-D operationalizes."),
];

const design = [
  H1("Experimental Design"),
  H2("Three-Stratum Alert Generation"),
  body("Whether information exclusion helps depends on whether the excluded information was needed. We therefore generate three populations and report them separately.", { noIndent: true }),
  body("*Stratum A (trusted-sufficient).* T0 and T1 support a verdict, but no single field announces it and the class-conditional distributions overlap, so no rule attains perfect accuracy.", { noIndent: true }),
  body("*Stratum B-syn (parse-required).* T0 and T1 are drawn from the same distribution regardless of label. The verdict follows from *parsing* a T2 string: a percent-encoded query that decodes to a path traversal versus a multi-byte search term; a filename whose final extension is executable; an apostrophe that is SQL logic versus an Irish surname.", { noIndent: true }),
  body("*Stratum B-ref (record-required).* The verdict requires *cross-checking* a T2 string against a trusted record, which we supply as a T0 field: an approved egress domain list, a sanctioned scanner agent list, a list of open change tickets. Ground truth is membership in that list.", { noIndent: true }),
  body("The third stratum addresses a problem that would otherwise make benign verdicts uninterpretable. Whether a hostname belongs to a contracted partner is not recoverable from the string's meaning; without a trusted record a model can only judge plausibility, and a benign verdict reached by finding an attacker's claim plausible is indistinguishable from one reached by verification. Since persona-hijack payloads fabricate exactly such identifiers, that ambiguity would sit on top of the phenomenon under study. Supplying the record as T0 makes the verdict checkable. It also sharpens the gate's position: the gate sees the list but not the string to be checked against it, so in this stratum it cannot complete the verification — which is the precise shape of the cost of exclusion."),
  body("Five signature families appear in both classes, so no signature is class-determining."),
  H2("Label Preservation Under Injection"),
  body("Appending a payload to a field can change the task rather than attack it. Appending text after a filename changes the final extension; appending to a hostname makes it a different hostname. If the verdict then changes, that is not evidence of injection. We therefore require that the ground truth survive the edit:", { noIndent: true }),
  body("Y(original event) = Y(modified event),", { noIndent: true, align: AlignmentType.CENTER }),
  body("where Y is not a copy of the stored label but the output of an executable oracle encoding each template's decisive property — final extension for the upload template, decoded path for the encoded-request template, SQL logic syntax for the credential template, and list membership for the three record-required templates. Injection proceeds field by field in random order and accepts the first compatible field for which the oracle still returns the original label; fields that would change it are rejected and recorded. On a 900-alert sample this rejects 30 filename placements, which is exactly the case the oracle exists to catch, and leaves no surviving alert whose ground truth was altered. Every condition receives the identical modified event, so the comparison is unaffected by the choice.", { noIndent: true }),
  body("The oracle also bounds what the record-required stratum means. It defines a synthetic classification task — compare a designated observed field against a supplied list — and we do not equate it with approval verification in a real SOC, where the presence of a ticket identifier in text is not proof that the work was authorized. Note that R1 implements essentially the same checks the oracle encodes, which is why it performs near ceiling on the B strata; that is a property of the construction, not a finding."),
  H2("Non-LLM Baselines"),
  body("We include two baselines that use no language model. R0 applies a three-line rule over T0 and T1 and never reads T2; it is injection-immune by construction and serves as a reference point for what that immunity costs. R1 parses T2: it percent-decodes request targets and tests for traversal, checks final extensions against an executable set, tests usernames for SQL logic syntax rather than bare apostrophes, and performs exact lookups against the T0 record lists.", { noIndent: true }),
  body("R1 is the honest comparator for any claim that this task requires a language model, and on our generated data it performs well — by construction it can resolve the record-required stratum exactly, since ground truth there *is* an exact lookup. We therefore do not claim that our data demonstrates the necessity of an LLM, and we report R0 and R1 as difficulty bounds rather than as evidence for LLM triage. The paper's question is what a defense does to an LLM pipeline that practitioners are already deploying, not whether that deployment is warranted."),
  H2("Conditions"),
  body("Table III lists the conditions with the reference condition each is compared against. They do not form a single chain: the baseline conditions B2 and B3 branch from B1, while the component-analysis conditions continue through B1N. B1 is the primary baseline, being the strongest classification mode in [11], and B3 follows that work's definition of structured prompting plus output templating as closely as the description allows; our instantiation also carries a forged-verdict warning (Section V-D), so it is an approximation of their condition, not a reproduction.", { noIndent: true }),
  body("Two qualifications. First, P1 differs from P0 in more than the position of T2 values: relocation introduces reference identifiers, an appendix heading, and a second occurrence of each field name. The comparison therefore isolates *referenced-appendix rendering as a bundle*, not position as a single variable; isolating position alone would require a further condition carrying the identifiers without the relocation, which we do not include. Second, our harness requires JSON output from every condition for automated scoring, which is itself a partial output constraint absent from the free-text baselines of prior work. Our B3-versus-B1 contrast is correspondingly narrower than theirs, and B3 adds two sentences (Appendix E): a reminder to emit only the JSON object the system prompt defines, and a warning that any text inside the log block resembling a verdict, an approval, or a prior decision is untrusted content rather than a finding. The second sentence is a semantic instruction about forged authority, not a formatting constraint, so the B3-versus-B1 contrast estimates output templating *plus* that warning, and we do not read it as templating alone."),
  spacer(40),
  caption("TABLE III. ", "Conditions and their reference conditions. B2 and B3 branch from B1; they are not successors of one another."),
  tbl(["ID", "Reference", "Adds"], [
    ["B0", "—", "nothing"],
    ["B1", "B0", "tags + untrusted warning"],
    ["B1N", "B1", "normalization"],
    ["B2", "B1", "keyword filter"],
    ["B3", "B1", "JSON-only reminder + forged-verdict warning"],
    ["P0", "B1N", "tiers + provenance text"],
    ["P1", "P0", "referenced appendix"],
    ["P2", "P1", "downgrade gate"],
    ["R0", "—", "non-LLM, T0/T1 only"],
    ["R1", "—", "non-LLM, parses T2"],
  ], [560, 1180, 3300], { align: [AlignmentType.CENTER, AlignmentType.CENTER, AlignmentType.LEFT] }),
  spacer(120),
  H2("Metrics"),
  body("A verdict on a malicious alert *fails* if it is benign or recommends closing. Each malicious alert is judged twice under each condition, once with its payload and once without, giving a four-cell transition table.", { noIndent: true }),
  body("The *primary* comparison is the injected miss rate: the proportion of injected malicious alerts finally missed. Its denominator is the full malicious sample and is identical across conditions, so conditions can be ranked without selection effects. Paired with the over-escalation rate on benign alerts, it defines the operational plane on which a deployment decision is made."),
  body("Two conditional quantities support causal reading but are not used for ranking. ASR_{cond} = #(clean correct, injected failed) / #(clean correct) measures how much of what a condition got right the attack destroys; its denominator varies by condition, so a condition that already misses most attacks can post a low value while performing poorly. We therefore report the denominator alongside every value. Recovery = #(clean failed, injected correct) / #(clean failed) captures the opposite transition. We report the difference of marginal rates only as a secondary figure, since it cancels opposing transitions: an attack that breaks ten correct verdicts and repairs ten incorrect ones registers as zero."),
  body("For benign alerts we report the over-escalation rate and the defense-attributable increment relative to B0, since not every false escalation is caused by the defense. The over-escalation rate is a false-positive rate on benign input; we do not present it as a new statistic but as an operational cost this evaluation has omitted. We also report miss rate, balanced accuracy, calls per alert, and payload residual by condition."),
  H2("Statistics"),
  body("Every alert is evaluated under every condition, so the data are paired and clustered by alert. Condition comparisons use the exact McNemar test [22] on discordant pairs. Confidence intervals for transition-derived rates use a bootstrap resampled at the alert level [23]. When the event count is zero the nonparametric bootstrap returns an interval collapsed to a point, which would assert an upper bound of zero; in that case we substitute a Wilson interval [18] on the appropriate denominator and record which method was used.", { noIndent: true }),
  body("Six comparisons are pre-specified and corrected for multiplicity by the Holm procedure; pre-specification does not by itself remove the multiplicity problem. Five concern overall effects — P1 vs P0, P0 vs B1N, B1N vs B1, P1 vs B1, and P2 vs P1 on injected miss rate. The sixth carries the stratified claim: P2 vs P1 on over-escalation *within the record-required stratum*, which is where the excluded information was needed. Making one stratified comparison confirmatory keeps the paper's central claim testable; all remaining analyses by stratum, payload class, and pipeline are exploratory and excluded from the correction, since with 108 malicious alerts per condition divided across three strata and four payload classes the per-cell counts fall to roughly nine."),
  body("The McNemar input is stated once to avoid confusion with the transition analysis: *for each pair of conditions we compare, on the same injected alert, whether each condition finally missed it (malicious alerts) or finally escalated it (benign alerts).* The clean-versus-injected transition table is a separate analysis and its counts are never mixed into a condition comparison. Conditional rates whose denominator is empty are reported as N/A, not as zero."),
  body("A comparison that does not reach significance does not establish equivalence. Where a pre-specified comparison fails, we report that the advantage was not demonstrated at this sample size, not that the effect is absent; establishing absence would require a pre-stated tolerance and an equivalence test, which we do not perform."),
  H2("Judge Protocol"),
  body("Every judgment is an independent, stateless call with a fixed system prompt; no two alerts share a context window. Section VI-B reports the pilot evidence behind this requirement. Responses are constrained to JSON; unparseable responses are scored as escalate and counted. Responses are cached by content hash so re-analysis is free and exact outputs are preserved. For gpt-4o-mini every call used temperature 0 and a fixed seed. The frontier endpoint rejected both parameters, so those calls ran under the provider's default sampling; the two models therefore differ in decoding as well as in weights, and we do not attribute differences between them to either alone. Calls were submitted through the provider's batch interface, which has rate limits separate from the interactive endpoint.", { noIndent: true }),
  body("Conditions that render byte-identical prompts share one cached response. This is deliberate: the two members of such a pair differ only in what happens outside the prompt, so sharing the response removes sampling noise from the comparison rather than introducing it. It also bounds what some comparisons can show. Normalization is a no-op on most alerts, so B1N renders the same prompt as B1 on 258 of 288 items and B2 the same as B1 on 273 of 288; those two comparisons can differ only on the remainder. P2's first-stage prompt is identical to P1's on every item by construction, so P2 versus P1 isolates the gate exactly. Of 2,304 judgments per model, 1,485 are distinct prompts."),
  H2("Post Hoc Follow-Up"),
  body("After the main results were known we ran additional conditions, reported separately in Sections VII-E and VII-G and not included in the pre-specified family. Two decompose the provenance note used by P0 and P1 into cumulative clauses; a third keeps P1's layout and replaces the label and note with neutral wording; a fourth applies the downgrade gate to every alert as a standalone classifier. All four were motivated by the results or by review and should be read as exploratory.", { noIndent: true }),
];

const pilot = [
  H1("Pilot Studies and Protocol Findings"),
  body("Three pilot iterations preceded the main experiment, using a small-model judge accessed through an agent interface rather than a stateless API. They are not evidence for or against the methods. We report two protocol findings and one recurring observation, and state in Section VI-E what they cannot establish.", { noIndent: true }),
  H2("Label Recoverability"),
  body("An initial generator used signature names that determined the class. Under it, every condition including the unprotected baseline produced zero injection successes on the 28 injected alerts observed. With a trusted field that announces the answer, the task is lookup rather than triage, and a defense comparison cannot be made. Replacing it with class-ambiguous signatures restored a measurable rate. We report this as an observation about that generator rather than as a general law about injection.", { noIndent: true }),
  H2("Context Sharing Between Conditions"),
  body("A second pilot ran one judge per condition, each processing a 48-item queue. A third mixed all conditions into shared blinded batches. The unprotected baseline's injection success rate measured 28.6% in the first arrangement and 5.6% in the second (Table IV). The arrangements differ in queue composition and sample size as well as in structure, so this is not a controlled single-factor comparison and we do not treat the two values as bounds on a true rate.", { noIndent: true }),
  body("A plausible account of the gap is leakage between conditions: the appendix rendering explicitly names authority-claiming strings as evasion evidence, and a judge that reads such items early in a mixed batch may apply that framing to unprotected items later in the same batch. We therefore require that conditions not share a judge context, which stateless per-item calls satisfy by construction. The requirement is stated narrowly: *when comparing conditions on independent single-alert classification, context must not be shared across conditions.* We do not claim that stateful judges cannot measure the phenomenon in general. A deployed system correlating multiple alerts is a stateful agent whose state is part of what should be evaluated; that is a different study."),
  spacer(40),
  caption("TABLE IV. ", "Unprotected baseline under two pilot arrangements. Sample sizes and queue composition differ; not a controlled comparison."),
  tbl(["Arrangement", "Rate", "n", "Queue"], [
    ["Per-condition sessions", "28.6%", "28", "48"],
    ["Mixed blinded batches", "5.6%", "36", "60"],
  ], [2020, 900, 700, 1420]),
  spacer(80),
  H2("Over-Escalation Recurred"),
  body("In both arrangements, defensive prompt language was associated with higher over-escalation. The constrained baseline produced the highest rate (10.0% and 16.7%), the appendix rendering an intermediate one (0.0% and 8.3%), and the unprotected condition the lowest in the blinded arrangement (4.2%). Both arrangements are confounded, and we cannot show that their confounds act in opposite directions; the observation is that the ordering recurred, which motivates measuring it properly rather than settling it.", { noIndent: true }),
  H2("Gate Ablation"),
  body("In the per-condition pilot the gate reviewed 21 first-stage benign verdicts and overrode four. All four were benign; the single injection success it was intended to catch passed through. Over-escalation rose from 0% to 20% and cost from 1.00 to 1.44 calls per alert. The four overrides were internal backup transfers whose benign character rested on a partner-archive destination hostname — a T2 field the gate cannot see. This is the context-dependence failure anticipated in [10], and it motivates the record-required stratum of Section V-A, where that situation is constructed deliberately and with checkable ground truth.", { noIndent: true }),
  H2("What the Pilots Cannot Establish"),
  body("The pilot judge was not a temperature-0 API call, its exact model identifier and any interface-level system instructions were not controlled, and items shared context within a batch. Pilot magnitudes should not be read as estimates of any rate. They motivated design decisions; they do not support claims about the methods.", { noIndent: true }),
];

const results = [
  H1("Results"),
  body(`This section reports the main experiment under the stateless protocol of Section V-G. Two models are evaluated: gpt-4o-mini, chosen to sit alongside the classification figures of [11], and the frontier endpoint gpt-6-astra. Each runs N = 60 alerts per seed over three seeds, yielding 108 malicious and 72 benign alerts per condition. Table V(c) accounts for every evaluation across the pre-specified and post hoc conditions. Every LLM response on both models parsed as JSON; none was scored by the fail-closed rule. The consumption path is *parse* throughout; the *serialize* and *raw* contrasts described in Section III-C were not run and are not reported.`, { noIndent: true }),

  H2("Primary Operational Comparison"),
  body(`Table V gives the co-primary pair for every condition on both models. Alongside it we report three *clean-task* quantities computed on attack-free judgments only: the true-positive rate, the false-positive rate (which is the over-escalation rate), and Youden's J = TPR − FPR with the balanced accuracy it implies. These describe how well a condition separates malicious from benign alerts when nothing is attacking it, and are kept distinct from the injected miss rate, which is measured under attack. J summarizes classification quality at the operating point each condition chose; it does not by itself separate a moved threshold from a change in how cases are ranked, since J also varies along a fixed ROC curve. We report it with a 95% interval computed by Newcombe's hybrid score method for the difference of two independent proportions [24], which combines the Wilson intervals of TPR and FPR (disjoint alert sets) and does not collapse at the boundary, so that a point estimate near zero is read with its uncertainty. A point estimate at J ≤ 0 is one a random classifier with the same false-positive rate would match.`, { noIndent: true }),
  body(`On gpt-4o-mini the ordering on injected misses runs from the unprotected baseline (${pc(C4.B0_naive.injected_miss)}%) through the structured baselines (${pc(C4.B3_constrained.injected_miss)}–${pc(C4.B2_sanitized.injected_miss)}%) to the provenance conditions (${pc(C4.P0_inline_prov.injected_miss)}% and ${pc(C4.P1_pag_render.injected_miss)}%) and the gate (${pc(C4.P2_pag_full.injected_miss)}%). Over-escalation runs the same way: ${pc(C4.B0_naive.oer)}%, ${pc(C4.B1_structured.oer)}–${pc(C4.B3_constrained.oer)}%, ${pc(C4.P1_pag_render.oer)}–${pc(C4.P0_inline_prov.oer)}%, ${pc(C4.P2_pag_full.oer)}%. Relative to B1, P0 and P1 lower misses and raise over-escalation; P2 lowers misses further and raises over-escalation further. Clean-task J declines from ${pp(C4.B0_naive.youden_j)} at B0 through the structured baselines to ${pp(C4.P0_inline_prov.youden_j)} at P0 and ${pp(C4.P1_pag_render.youden_j)} at P1; both provenance conditions have intervals that include zero (P0 ${jci(C4.P0_inline_prov)}, P1 ${jci(C4.P1_pag_render)}). P2 escalated all 288 of its judgments and has J = 0 exactly (${jci(C4.P2_pag_full)}); that it escalated everything in this sample does not guarantee it would on new alerts, which is what the interval expresses. Among the pre-specified conditions the unprotected baseline has the highest clean-task balanced accuracy on this model.`),
  body(`On gpt-6-astra no LLM condition missed any malicious alert, injected or clean, so the security column is uninformative and the comparison rests entirely on cost. Over-escalation rises from ${pc(C6.B0_naive.oer)}% at B0 to ${pc(C6.B1_structured.oer)}–${pc(C6.B3_constrained.oer)}% for the structured baselines, ${pc(C6.P1_pag_render.oer)}% and ${pc(C6.P0_inline_prov.oer)}% for the provenance conditions, and ${pc(C6.P2_pag_full.oer)}% for the gate. J falls from ${pp(C6.B0_naive.youden_j)} to ${pp(C6.P1_pag_render.youden_j)}, ${pp(C6.P0_inline_prov.youden_j)}, and 0. The non-LLM parser R1 is model-independent and has the highest clean-task J and balanced accuracy of any condition on both models (J = ${pp(C4.R1_rule_t2parser.youden_j)}), although on gpt-6-astra its injected miss rate (${pc(C4.R1_rule_t2parser.injected_miss)}%) is above the LLM conditions' zero; Section V-C states why this is a property of the benchmark's construction and not evidence about whether the task needs a language model.`),
  spacer(60),
  caption("TABLE V. ", "Primary comparison, three seeds pooled (108 malicious, 72 benign per condition). OER carries a Wilson 95% interval. TPR, J, and BA are clean-task (attack-free); J = TPR − FPR, with a Newcombe hybrid-score 95% interval [24]. Calls/eval. is calls per judgment over 288 judgments per condition (both variants of malicious alerts), not per operational alert. R0 and R1 are deterministic and identical across models.", { keepNext: true }),
  tbl(["Cond.", "Inj. miss", "OER [95% CI]", "TPR", "J [95% CI]", "BA", "Calls"],
    ["B0_naive", "B1_structured", "B1N_structured_norm", "B2_sanitized", "B3_constrained",
     "P0_inline_prov", "P1_pag_render", "P2_pag_full", "R0_rule_t01", "R1_rule_t2parser"].map(c => {
      const t = C4[c];
      return [c.split("_")[0], pc(t.injected_miss), `${pc(t.oer)} ${ci(t.oer_ci)}`, pc(t.tpr), `${pp(t.youden_j)} ${jci(t)}`, pc(t.balanced_acc), M4.calls_per_item[c].toFixed(2)];
    }), [540, 600, 1080, 520, 1280, 520, 500]),
  caption("", "(a) gpt-4o-mini, temperature 0."),
  spacer(40),
  tbl(["Cond.", "Inj. miss", "OER [95% CI]", "TPR", "J [95% CI]", "BA", "Calls"],
    ["B0_naive", "B1_structured", "B1N_structured_norm", "B2_sanitized", "B3_constrained",
     "P0_inline_prov", "P1_pag_render", "P2_pag_full"].map(c => {
      const t = C6[c];
      return [c.split("_")[0], pc(t.injected_miss), `${pc(t.oer)} ${ci(t.oer_ci)}`, pc(t.tpr), `${pp(t.youden_j)} ${jci(t)}`, pc(t.balanced_acc), M6.calls_per_item[c].toFixed(2)];
    }), [540, 600, 1080, 520, 1280, 520, 500]),
  caption("", "(b) gpt-6-astra, provider default sampling. R0 and R1 as in (a)."),
  spacer(40),
  tbl(["Model", "Conditions", "Logical evaluations", "+ P2 2nd stage", "API calls (distinct prompts)", "Served from cache"],
    Object.entries(RES.accounting_full).map(([m, A]) => [m, nm(A.conditions), A.logical_evaluations.toLocaleString(), nm(A.p2_second_stage), A.api_calls.toLocaleString(), nm(A.cache_reuse)]),
    [900, 700, 1000, 800, 1100, 740]),
  caption("", "(c) Execution accounting per model over all twelve LLM conditions (eight pre-specified, four post hoc), 288 evaluations each. An API call is a distinct (system prompt, user prompt, seed) triple; byte-identical prompts across conditions, and the gate prompts P2 and G share, are called once and otherwise served from cache. R0 and R1 make no calls."),
  spacer(80),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 60 }, keepNext: true,
    children: [new ImageRun({ data: fs.readFileSync(path.join(__dirname, "fig1_safety_cost.png")), transformation: { width: 318, height: 571 }, type: "png" })] }),
  caption("Fig. 1. ", "Both models, the eight pre-specified conditions, R0/R1, and the post hoc N and G (L0, L1 omitted), three seeds pooled. (a) The pre-specified operational pair; the lower left is better. (b) Attack-free discrimination with the chance diagonal; a point on the diagonal has J = 0. R0 and R1 are deterministic and shown once. P2 and G coincide at the escalate-everything corner on both models. On both models P0, P1, and P2 lie far to the right of the baselines; on gpt-4o-mini P0 and P1 lie near the diagonal while the neutral rewording N sits with the baselines."),
  spacer(80),

  H2("Pre-Specified Comparisons"),
  body(`Table VI reports the six pre-specified comparisons with raw and Holm-adjusted p-values. On gpt-4o-mini three reach significance, and all three are comparisons in which the more escalation-prone condition wins on malicious alerts: provenance framing over the normalized structured baseline (P0 vs B1N, ${nm(M4.prespecified[1].a_only)}/${nm(M4.prespecified[1].b_only)} discordant), the proposed rendering over the strongest prior baseline (P1 vs B1, ${nm(M4.prespecified[3].a_only)}/${nm(M4.prespecified[3].b_only)}), and the gate over the rendering (P2 vs P1, ${nm(M4.prespecified[4].a_only)}/${nm(M4.prespecified[4].b_only)}). Read against Table V, each of these is what a condition that escalates more of everything must produce on malicious alerts; the test is valid but the quantity it tests is not discrimination.`, { noIndent: true }),
  body(`The two comparisons that isolate the paper's proposed mechanisms do not reach significance. Relocating attacker text to a referenced appendix over labeling it in place (P1 vs P0) gives ${nm(M4.prespecified[0].a_only)}/${nm(M4.prespecified[0].b_only)} discordant pairs, ${peq(M4.prespecified[0].p)}: the two conditions disagree on nine alerts and split them nearly evenly. Normalization (B1N vs B1) gives ${nm(M4.prespecified[2].a_only)}/${nm(M4.prespecified[2].b_only)}, which is the ceiling Section V-G anticipated for a comparison whose prompts coincide on 258 of 288 items. The stratified confirmatory comparison — the gate's over-escalation cost within the record-required stratum — gives ${nm(M4.prespecified[5].a_only)}/${nm(M4.prespecified[5].b_only)}, all four discordant pairs in the direction of the gate escalating more, ${peq(M4.prespecified[5].p)} (Holm ${pv(M4.prespecified[5].p_holm)}). The direction is the one the design predicted; the sample does not establish it. On gpt-6-astra every malicious-alert comparison has zero discordant pairs, since no condition missed anything, and the stratified benign comparison also has none.`),
  spacer(60),
  caption("TABLE VI. ", "Pre-specified comparisons, exact McNemar on discordant pairs (b = first condition only fails, c = second only fails), Holm-corrected over the family of six. gpt-6-astra: all six have b = c = 0.", { keepNext: true }),
  tbl(["Comparison", "Label", "b/c", "p", "p_Holm", "Sig."],
    M4.prespecified.map(r => [
      `${r.a.split("_")[0]} vs ${r.b.split("_")[0]}${r.stratum ? " (" + r.stratum + ")" : ""}`,
      r.label === "malicious" ? "mal." : "ben.",
      `${nm(r.a_only)}/${nm(r.b_only)}`, pv(r.p), pv(r.p_holm), r.significant ? "yes" : "no"]),
    [1560, 520, 620, 760, 760, 560]),
  spacer(80),

  H2("Transition Analysis"),
  body(`Table VII gives the four transition cells for gpt-4o-mini together with the conditional attack success rate and its condition-specific denominator. The denominators range from ${nm(C4.B0_naive.asr_denom)} to ${nm(C4.P2_pag_full.asr_denom)}, which is why ASR_{cond} is not used for ranking: a condition that already misses much of the clean sample has fewer correct verdicts for the attack to break. Read with that caveat, the attack breaks ${pc(C4.B0_naive.asr_cond, 0)}% of what the unprotected baseline gets right, ${pc(C4.B1_structured.asr_cond, 0)}% for the structured baseline, ${pc(C4.B3_constrained.asr_cond, 0)}% for the templated one, and ${pc(C4.P1_pag_render.asr_cond, 0)}% for the appendix rendering. The recovery cell — alerts the payload turned from missed to caught — is small everywhere except under provenance framing, where a payload that makes an authority claim inside a block the prompt has labeled attacker-writable is itself a signal. On gpt-6-astra all 108 pairs in every condition fall in the (correct, correct) cell.`, { noIndent: true }),
  spacer(60),
  caption("TABLE VII. ", "Transition cells for malicious alerts, gpt-4o-mini: clean verdict → injected verdict. cc = correct→correct, cf = correct→failed, fc = failed→correct, ff = failed→failed. ASR_cond = cf / (cc + cf); its denominator is shown. Recovery = fc / (fc + ff).", { keepNext: true }),
  tbl(["Cond.", "cc", "cf", "fc", "ff", "ASR_cond (denom.)", "Recovery"],
    ["B0_naive", "B1_structured", "B1N_structured_norm", "B2_sanitized", "B3_constrained",
     "P0_inline_prov", "P1_pag_render", "P2_pag_full"].map(c => {
      const t = C4[c];
      return [c.split("_")[0], nm(t.cc), nm(t.cf), nm(t.fc), nm(t.ff), `${pc(t.asr_cond)}% (${nm(t.asr_denom)})`, t.recovery === null ? "n/a" : pc(t.recovery) + "%"];
    }), [560, 460, 460, 460, 460, 1400, 860]),
  spacer(80),

  H2("Stratified Results"),
  body(`Table VIII gives the injected miss rate by stratum on gpt-4o-mini. The design's expectation was that exclusion would help in the trusted-sufficient stratum and pay in the record-required one. The data show something simpler. Every LLM condition finds the parse-required stratum easiest and the record-required stratum hardest, and the provenance conditions reduce misses in all three strata by roughly the same proportion — because they escalate more of everything in all three. R0, which never reads attacker-writable fields, collapses in the two strata that need them (${pc(M4.by_stratum.R0_rule_t01["B-syn"].injected_miss)}% and ${pc(M4.by_stratum.R0_rule_t01["B-ref"].injected_miss)}%); R1, which parses them, misses nothing there and is limited only by the trusted-sufficient stratum where it falls back to R0's rule. On gpt-6-astra every LLM cell is zero.`, { noIndent: true }),
  spacer(60),
  caption("TABLE VIII. ", "Injected miss rate (%) by stratum, gpt-4o-mini. Per-stratum counts are 37, 35, and 36 malicious alerts; these cells are exploratory.", { keepNext: true }),
  tbl(["Cond.", "A (trusted-sufficient)", "B-syn (parse-required)", "B-ref (record-required)"],
    ["B0_naive", "B1_structured", "B3_constrained", "P0_inline_prov", "P1_pag_render", "P2_pag_full", "R0_rule_t01", "R1_rule_t2parser"].map(c => {
      const s = M4.by_stratum[c];
      return [c.split("_")[0], pc(s.A.injected_miss), pc(s["B-syn"].injected_miss), pc(s["B-ref"].injected_miss)];
    }), [700, 1400, 1400, 1400]),
  spacer(80),

  H2("Gate Behavior"),
  body(`The downgrade gate was invoked whenever P1's first stage proposed closing an alert: ${nm(M4.gate.fired)} times on gpt-4o-mini and ${nm(M6.gate.fired)} times on gpt-6-astra. It rejected the downgrade in every one of those ${nm(M4.gate.fired + M6.gate.fired)} cases. Table IX breaks the invocations down, because the gate is evaluated only on the subset P1 selected and that subset differs sharply between models. On gpt-4o-mini, ${nm(M4.gate.malicious_seen)} of the ${nm(M4.gate.fired)} invocations were evaluations of malicious alerts P1 had proposed to close — its ${nm(C4.P1_pag_render.injected_miss_k)} misses under injection, of which ${nm(C4.P1_pag_render.cf)} were correct-to-failed transitions caused by the payload and ${nm(C4.P1_pag_render.ff)} were missed in the clean state as well — and the gate's rejection of those was correct; the remaining ${nm(M4.gate.benign_seen)} were benign alerts, all in the record-required stratum, and the gate rejected those too. On gpt-6-astra P1 never proposed closing a malicious alert, so all ${nm(M6.gate.fired)} invocations were benign alerts, in the trusted-sufficient and parse-required strata, and every rejection was a false escalation.`, { noIndent: true }),
  body(`Two things follow. First, on the small model the gate did what it was built to do on the malicious side: no injection-induced miss survived it. Second, on the alerts P1 sent it the gate never accepted a downgrade, but that subset is selected, and on gpt-4o-mini it contained no benign alert from the trusted-sufficient stratum. To remove the selection we ran the gate as a standalone classifier on every alert (condition G, post hoc), on both models. On each it accepted a downgrade for none of its 288 judgments: all 108 malicious alerts, in both variants, and all ${nm(F4.gate_alone_benign.total.n)} benign alerts, in every stratum. Table IX(b) sets this beside R0, the three-line rule that reads exactly the same sensor-generated fields: R0 closes ${nm(F4.gate_alone_benign.total.r0_closed)} of the ${nm(F4.gate_alone_benign.total.n)} benign alerts, and ${nm(F4.gate_alone_benign.A.r0_closed)} of ${nm(F4.gate_alone_benign.A.n)} in the trusted-sufficient stratum. That comparison must be read with care: R0 also misses ${pc(M4.by_stratum.R0_rule_t01.A.injected_miss, 0)}% of malicious alerts in that stratum, so closing many benign alerts does not by itself show that the trusted fields justify a *safe* close, and in the parse-required and record-required strata the design itself withholds from T0/T1 the information the verdict needs. What the comparison does show is narrower: in the trusted-sufficient stratum the sensor fields carry a classification signal that a trivial rule exploits, and the gate closed nothing there either. First-stage selection is excluded as the explanation; the pattern is consistent with extreme conservatism of the gate configuration we tested; attributing it to the prompt rather than to the task would require comparing gate prompts, which we did not do. The cost per judgment under P2 (${M4.calls_per_item.P2_pag_full.toFixed(2)} and ${M6.calls_per_item.P2_pag_full.toFixed(2)} calls) is low only because the first stage rarely proposed closing anything.`),
  spacer(60),
  caption("TABLE IX. ", "(a) Gate invocations under P2, by stratum, ground truth, and variant; every invocation was rejected on both models. Benign alerts carry no payload and are marked —. (b) Gate applied to every alert (condition G, post hoc): benign alerts closed, beside R0 on the same sensor-generated fields.", { keepNext: true }),
  tbl(["Model", "Stratum", "Truth", "Variant", "Invoked", "Rejected"],
    [["gpt-4o-mini", M4], ["gpt-6-astra", M6]].flatMap(([m, M]) =>
      M.gate.cells.map((c, i) => [i === 0 ? m : "", c.stratum, c.label, c.label === "benign" ? "—" : c.variant, nm(c.n),
                                   c.outcome === "rejected" ? nm(c.n) : "0"])),
    [1000, 760, 900, 760, 800, 820]),
  caption("", "(a) Under P2."),
  spacer(40),
  tbl(["Stratum", "Benign alerts", "Closed by gate (G)", "Closed by R0"],
    ["A", "B-syn", "B-ref", "total"].map(st => {
      const d = F4.gate_alone_benign[st];
      return [st === "total" ? "All" : st, nm(d.n), nm(d.gate_closed), nm(d.r0_closed)];
    }), [1200, 1300, 1400, 1140]),
  caption("", "(b) Gate alone versus R0, identical inputs (T0/T1 fields only). The gate closed zero benign alerts on gpt-6-astra as well; R0 is deterministic and identical across models."),
  spacer(80),

  H2("Frontier Model"),
  body(`On gpt-6-astra the injection corpus produced no effect. Across eight conditions, three seeds, and 108 malicious alerts each, no injected verdict differed from its clean counterpart, and no malicious alert was closed in either state. The Wilson upper bound on a zero count of 108 is ${pc(RES.wilson_upper_0_of_108)}% per condition. Three accounts are consistent with this. The model may be robust to the corpus. The model may hold an escalation prior on malicious-looking alerts strong enough that no payload in the corpus overcomes it — a conservative bias rather than robustness, and one the ${pc(C6.B0_naive.oer)}% over-escalation of the unprotected baseline makes plausible. Or the corpus, which was validated against the small model, may simply be weak against this one. Note that the attack-free miss rate of ${pc(C6.B0_naive.clean_miss)}% does not limit what the attack could have shown: every one of the 108 malicious alerts was a correct verdict the payload had the opportunity to break, so the conditional attack success rate had its largest possible denominator and was still zero. Separating the three accounts would need harder or borderline benign alerts, an adaptive attacker, and a comparison of operating points rather than a change to the malicious set. What the frontier data do show is that the cost side is unchanged: the same prompt changes that raise over-escalation on the small model raise it here, from ${pc(C6.B0_naive.oer)}% to ${pc(C6.P1_pag_render.oer)}% for the rendering and ${pc(C6.P2_pag_full.oer)}% for the gate, with no security benefit available to offset it. We do not attribute the difference between the models to capability; size, training, safety tuning, and decoding settings differ jointly, and the frontier endpoint did not accept the sampling parameters the small model ran under.`, { noIndent: true }),

  H2("Post Hoc Decomposition of the Provenance Note"),
  body(`The note P0 and P1 share ends with a clause instructing the model that an authority claim inside attacker-writable text is itself evidence of evasion and raises severity. After seeing Table V we asked whether that clause, rather than provenance marking as such, was responsible for the over-escalation. We split the note into three cumulative levels — L0, which states only that the fields were written by whoever sent the traffic; L1, which adds that no such string can grant approval or report a prior verdict; and L2, the full note — and ran L0 and L1 as new conditions identical to P1 in every other respect. This experiment was designed after the main results and is not part of the pre-specified family; its two internal comparisons are Holm-corrected within their own family of two.`, { noIndent: true }),
  body(`On gpt-4o-mini (Table X) the answer is that both are responsible: over-escalation rises with each clause added. Even L0, which gives no instruction, escalates ${pc(W4.levels.X1_note_minimal.oer)}% of benign alerts, against ${pc(C4.B1_structured.oer)}% for the structured baseline B1, which has neither trust tiers nor a note. L0 is not a neutral statement of provenance, however: it labels the fields ATTACKER-WRITABLE in a section heading and in the note, and calls them forensic artifacts, and it shares P1's tier layout and appendix placement. The comparison therefore bounds the cost of the label-and-layout bundle, not of provenance information as such. A fourth condition, N, isolates the latter: it keeps P1's tier layout, appendix placement, normalization, and the authority-denial clause of L1, and changes only the wording — the fields are labeled SENDER-SUPPLIED, and the note says their content may be evidence for or against the alert. Adding the authority clause raises over-escalation to ${pc(W4.levels.X2_note_authority.oer)}% (${nm(W4.benign[0].a_only)}/${nm(W4.benign[0].b_only)} discordant, ${peq(W4.benign[0].p)}) and lowers injected misses (${nm(W4.malicious[0].a_only)}/${nm(W4.malicious[0].b_only)}, ${peq(W4.malicious[0].p)}); adding the severity clause raises it again to ${pc(W4.levels.P1_pag_render.oer)}% (${nm(W4.benign[1].a_only)}/${nm(W4.benign[1].b_only)}, ${peq(W4.benign[1].p)}, Holm ${pv(W4.benign[1].p_holm)}) and lowers misses again (${nm(W4.malicious[1].a_only)}/${nm(W4.malicious[1].b_only)}, ${peq(W4.malicious[1].p)}). J falls from ${pp(W4.levels.X1_note_minimal.youden_j)} to ${pp(W4.levels.X2_note_authority.youden_j)} to ${pp(W4.levels.P1_pag_render.youden_j)}. Each clause buys security and pays for it in the same coin, and the exchange rate is unfavorable at every step.`),
  body(`The neutral condition locates most of the effect. N and L1 carry the same authority-denial clause and differ in the label and in the framing of the content as possible evidence; they differ on ${nm(fpair(F4, "X2_note_authority", "X3_note_neutral").benign.a_only)} benign alerts in one direction and none in the other (${peq(fpair(F4, "X2_note_authority", "X3_note_neutral").benign.p)}), and on ${nm(fpair(F4, "X2_note_authority", "X3_note_neutral").malicious.b_only)} malicious alerts the other way (${peq(fpair(F4, "X2_note_authority", "X3_note_neutral").malicious.p)}). The label-and-framing change alone moves ${nm(fpair(F4, "X2_note_authority", "X3_note_neutral").benign.a_only)} benign alerts into escalation and ${nm(fpair(F4, "X2_note_authority", "X3_note_neutral").malicious.b_only)} malicious ones out of the miss column. Against the structured baseline B1, which has no tiers and no note, no difference was detected on either axis at this sample size (benign ${nm(fpair(F4, "X3_note_neutral", "B1_structured").benign.a_only)}/${nm(fpair(F4, "X3_note_neutral", "B1_structured").benign.b_only)}, ${peq(fpair(F4, "X3_note_neutral", "B1_structured").benign.p)}; malicious ${nm(fpair(F4, "X3_note_neutral", "B1_structured").malicious.a_only)}/${nm(fpair(F4, "X3_note_neutral", "B1_structured").malicious.b_only)}, ${peq(fpair(F4, "X3_note_neutral", "B1_structured").malicious.p)}), with an injected miss rate of ${pc(FN4.injected_miss)}%, an over-escalation rate of ${pc(FN4.oer)}%, and the highest clean-task J of any LLM condition (${pp(FN4.youden_j)}). We did not perform an equivalence test, so this is a failure to detect a difference, not a demonstration of none; the supported statement is that N over-escalates far less than L1 and that its difference from B1 was not detected.`),
  body(`On gpt-6-astra no differences among the wordings were detected, and the neutral condition is no exception. The four wordings sit at ${pc(W6.levels.X1_note_minimal.oer)}%, ${pc(W6.levels.X2_note_authority.oer)}%, ${pc(W6.levels.P1_pag_render.oer)}%, and ${pc(FN6.oer)}% over-escalation; no ordering is monotone; no comparison among them reaches significance (L1 vs L0 ${nm(W6.benign[0].a_only)}/${nm(W6.benign[0].b_only)}, ${peq(W6.benign[0].p)}; L2 vs L1 ${nm(W6.benign[1].a_only)}/${nm(W6.benign[1].b_only)}, ${peq(W6.benign[1].p)}; L1 vs N ${nm(fpair(F6, "X2_note_authority", "X3_note_neutral").benign.a_only)}/${nm(fpair(F6, "X2_note_authority", "X3_note_neutral").benign.b_only)}, ${peq(fpair(F6, "X2_note_authority", "X3_note_neutral").benign.p)}). But N against the structured baseline is not the undetected difference it was on the small model: ${nm(fpair(F6, "X3_note_neutral", "B1_structured").benign.a_only)}/${nm(fpair(F6, "X3_note_neutral", "B1_structured").benign.b_only)} discordant, ${peq(fpair(F6, "X3_note_neutral", "B1_structured").benign.p)}, with N escalating more. The neutral rewording did not remove the cost on this model. N differs from B1 in several respects at once — trust tiers, appendix relocation, a provenance note, an authority clause, normalization — so the residual ${pp(FN6.oer - C6.B1_structured.oer, 0)} points cannot be attributed to any one of them, and the non-significance of the wording comparisons is not evidence that wording is irrelevant here. Nor do we test whether the two models differ: a large effect on one and an undetected effect on the other is not a demonstration of a difference between them. What the two runs support is this: the neutral rewording lowered over-escalation substantially on the small model and did not detectably lower it on the frontier model, and on the frontier model the neutral layout still costs more than the structured baseline.`),
  spacer(60),
  caption("TABLE X. ", "Provenance-note decomposition, post hoc. L0: provenance statement only. L1: + authority denial. L2 = P1: + severity instruction. N: L1's layout and authority clause with neutral label and framing. Benign comparisons test over-escalation; malicious comparisons test injected misses. All p-values in this table are uncorrected; the text reports L1 vs L0 and L2 vs L1 Holm-corrected within their family of two, and the N comparisons uncorrected.", { keepNext: true }),
  tbl(["Model", "Level", "Inj. miss", "OER", "J", "BA"],
    [["gpt-4o-mini", W4], ["gpt-6-astra", W6]].flatMap(([m, W]) =>
      [["X1_note_minimal", "L0"], ["X2_note_authority", "L1"], ["P1_pag_render", "L2 (P1)"]].map(([c, lab], i) => {
        const t = W.levels[c];
        return [i === 0 ? m : "", lab, pc(t.injected_miss), pc(t.oer), pp(t.youden_j), pc(t.balanced_acc)];
      }).concat((m === "gpt-4o-mini" ? FN4 : FN6) ? [(([FN]) => ["", "N (neutral)", pc(FN.injected_miss), pc(FN.oer), pp(FN.youden_j), pc(FN.balanced_acc)])([m === "gpt-4o-mini" ? FN4 : FN6])] : [])),
    [1000, 760, 820, 700, 760, 700]),
  spacer(60),
  tbl(["Model", "Comparison", "Benign b/c, p", "Malicious b/c, p"],
    [["gpt-4o-mini", W4], ["gpt-6-astra", W6]].flatMap(([m, W]) =>
      [0, 1].map(i => [i === 0 ? m : "", i === 0 ? "L1 vs L0 (authority)" : "L2 vs L1 (severity)",
        `${nm(W.benign[i].a_only)}/${nm(W.benign[i].b_only)}, ${pv(W.benign[i].p)}`,
        `${nm(W.malicious[i].a_only)}/${nm(W.malicious[i].b_only)}, ${pv(W.malicious[i].p)}`])
      .concat((([F]) => F.pairs ? [
        ["", "L1 vs N (label/framing)", `${nm(fpair(F, "X2_note_authority", "X3_note_neutral").benign.a_only)}/${nm(fpair(F, "X2_note_authority", "X3_note_neutral").benign.b_only)}, ${pv(fpair(F, "X2_note_authority", "X3_note_neutral").benign.p)}`, `${nm(fpair(F, "X2_note_authority", "X3_note_neutral").malicious.a_only)}/${nm(fpair(F, "X2_note_authority", "X3_note_neutral").malicious.b_only)}, ${pv(fpair(F, "X2_note_authority", "X3_note_neutral").malicious.p)}`],
        ["", "N vs B1", `${nm(fpair(F, "X3_note_neutral", "B1_structured").benign.a_only)}/${nm(fpair(F, "X3_note_neutral", "B1_structured").benign.b_only)}, ${pv(fpair(F, "X3_note_neutral", "B1_structured").benign.p)}`, `${nm(fpair(F, "X3_note_neutral", "B1_structured").malicious.a_only)}/${nm(fpair(F, "X3_note_neutral", "B1_structured").malicious.b_only)}, ${pv(fpair(F, "X3_note_neutral", "B1_structured").malicious.p)}`]] : [])([m === "gpt-4o-mini" ? F4 : F6]))),
    [1000, 1500, 1200, 1300]),
  spacer(80),

];

const discussion = [
  H1("Discussion"),
  H2("Operating Point Versus Discrimination"),
  body(`The central observation is that on this benchmark the security metric and the cost metric did not behave as independent quantities that a defense trades against each other. On gpt-4o-mini, relative to B1, both P0 and P1 reduced injected misses while increasing over-escalation; adding the gate to P1 reduced misses further and increased over-escalation further; and each clause added to the provenance note did the same (normalization, B1N, changed neither materially; P1 differs from P0 by less than one point on each axis, in opposite directions). The simplest account of a classifier whose true-positive and false-positive rates rise together toward the corner is that its decision threshold moved while its ranking of cases did not. Our data are consistent with that account but do not establish it: each condition yields one binary verdict per alert, and a prompt change can alter how the model weighs evidence, not only where it draws the line. What the data do show is that clean-task J falls from the unprotected baseline through the structured baselines to the provenance conditions, where its point estimates lie at or below zero, and that the gate sits at zero exactly. Distinguishing a moved threshold from a changed ranking would require eliciting a score or confidence from each condition and comparing detection at matched false-positive rates; we did not, and we state the threshold account as the interpretation we find most consistent with the pattern rather than as a result.`, { noIndent: true }),
  body(`This matters for how such results are reported. A study that measured only attack success would have concluded that provenance rendering reduced the injected miss rate by ${relred(C4.B1_structured.injected_miss, C4.P1_pag_render.injected_miss)}% relative to the structured baseline (${nm(C4.B1_structured.injected_miss * 108)} to ${nm(C4.P1_pag_render.injected_miss * 108)} of 108) and that adding a verification gate eliminates it. Both statements are true of our data. Neither describes a usable system. The over-escalation rate is not a secondary metric to be mentioned in a limitations section; on this evidence it is the quantity that determines whether the security number means anything.`),
  H2("What the Two Mechanisms Actually Did"),
  body(`The paper set out to separate two mechanisms. Relocating attacker text to a referenced appendix (D2) was hypothesized to make authority claims self-undermining by placing them inside a block the prompt has already described as quoted bytes. The pre-specified test did not demonstrate an advantage: P1 and P0 disagree on nine alerts and split them nearly evenly. A small effect of placement is not excluded at this sample size, but whatever the provenance conditions do on these data, the labeling and the note account for it and placement adds nothing we could detect. The downgrade gate (D3) was the only component with an information-flow guarantee. Invoked ${nm(M4.gate.fired + M6.gate.fired)} times across two models, it rejected the downgrade every time. On the small model most of those rejections were correct — the gate caught every injection-induced miss the first stage produced — and the cost fell on four benign alerts, all from the stratum built to be unverifiable from trusted fields. On the frontier model every invocation was a benign alert and every rejection a cost. Applied to every alert without the first stage's selection, on both models, it still accepted nothing, on benign alerts from every stratum, while a three-line rule reading the identical fields closed most of them. First-stage selection is therefore not the explanation. Whether the trusted fields were sufficient for a safe close is a harder question — R0 closes many benign alerts in the trusted-sufficient stratum but also misses many malicious ones there — and we do not claim to have settled it. What the gate-alone run shows is that under the one gate configuration we tested, the verifier never verified, on any alert, in any stratum, on either model. The guarantee — no attacker text reaches the verifier — was honored at the price of a verifier that declines. A less conservative gate prompt is possible and untested; comparing gate prompts is the experiment that would attribute the refusal to the prompt rather than to the task.`, { noIndent: true }),
  body("The failure modes of the two are different and should be kept apart. Appendix relocation showed no detectable advantage over inline provenance rendering. D3 did exactly what it guarantees, and then accepted nothing: whatever the trusted fields could have supported, this gate configuration did not use them to close an alert. Two redesigns differ in what they give up. A gate invoked only when a trusted signal crosses a threshold changes the invocation policy and keeps the input guarantee intact, since the gate still sees no attacker text. A gate that received tagged attacker text rather than none changes the inputs and trades the hard guarantee for a softer one. We tested neither."),
  H2("Wording, and What Replicates"),
  body(`The post hoc decomposition answers a question a reader of Table V should ask: is the over-escalation a property of provenance marking or of one alarming sentence? On the small model the answer is layered. The bare statement that fields were written by the sender — bundled, as it is in L0, with the ATTACKER-WRITABLE label and the appendix layout — already adds ${pp(W4.levels.X1_note_minimal.oer - C4.B1_structured.oer, 0)} points of over-escalation to the structured baseline; each subsequent clause adds to it and, in the same movement, subtracts from the miss rate. Rewording the label and the framing while keeping the authority clause (N) removes ${pp(W4.levels.X2_note_authority.oer - FN4.oer, 0).replace('+','')} of those points and gives back ${nm(fpair(F4, "X2_note_authority", "X3_note_neutral").malicious.b_only)} misses; what remains is not distinguishable from the structured baseline at this sample size. The strongest statement the small-model data support is therefore that, holding structure fixed, how the provenance is described changed the verdicts substantially in both directions. On gpt-6-astra the clauses are indistinguishable from one another, the neutral rewording did not detectably lower the cost, and the neutral layout still over-escalates more than the structured baseline; the residual is not attributed to any single element. Two models do not establish that the mechanism differs between models, and we do not test that. What both show is that the cost is real, that it is not confined to one alarming sentence, and that neither “the note is too alarming” nor “any provenance marking is harmful” is a safe generalization. On either model, the pattern is more consistent with a moved operating point than with improved discrimination, with the caveat of Section VIII-A.`, { noIndent: true }),
  H2("Attack Success Varied Between Models; the Cost Did Not"),
  body(`Sixty payloads that broke ${pc(C4.B0_naive.asr_cond, 0)}% of the small model's correct verdicts broke none of the frontier model's. Section VII-F gives three accounts of this — robustness, a conservative prior no payload overcame, and a corpus tuned to the small model — and our data do not separate them. But on both models we evaluated, the cost of the defenses did not depend on which it was: the same prompts raised over-escalation on the model on which this corpus produced no attack success. Two models do not license a claim of model independence; they do show that a practitioner adding a provenance layer to a triage pipeline may pay this cost whether or not the threat is live on their model, and that the threat is the part that changed between the two versions we tested. The stratified cost measurement, the transition metrics, and the protocol requirements are independent of which model is used; the injection rates are not, and should be re-measured rather than cited.`, { noIndent: true }),
  H2("The Parser"),
  body("R1 has the highest clean-task J and balanced accuracy of any condition on both models — though not the lowest injected miss rate on the frontier model — and we have been careful to say why that cannot be read as evidence that the task does not need a language model: R1 implements the same checks the ground-truth oracle uses, so its performance is a property of how the benchmark was built. It does support a narrower point. The information that resolves the parse-required and record-required strata is in the attacker-writable fields, and a component that reads those fields deterministically extracts it without being persuaded by them. The provenance conditions tried to get an LLM to read the same fields without being persuaded, and the price was that it stopped closing anything. Whether an LLM can be given the parser's immunity without the parser's rigidity is the question this paper leaves open.", { noIndent: true }),
];

const limits = [
  H1("Limitations and Threats to Validity"),
  body("*Synthetic alerts.* Alerts are generated from schemas, not captured from production, and lack vendor-specific fields, truncation artifacts, and the long tail of benign anomaly. The high over-escalation of even the unprotected baseline on the frontier model suggests the benign alerts are harder, or more suspicious-looking, than a production distribution would be. External validation on the AIT Alert Data Set [17] is the natural next step.", { noIndent: true }),
  body("*Task difficulty and the non-LLM baselines.* Our record-required stratum is resolvable by exact lookup, and our parse-required stratum by standard decoding, so a parser baseline performs well on both. This bounds what our data can say: it evaluates defenses applied to an LLM pipeline, and does not establish that the underlying task needs one."),
  body("*Why the frontier model showed no injection effect.* No malicious verdict changed under any condition on gpt-6-astra. Robustness to the corpus, a conservative escalation prior that no payload overcame, and a corpus tuned to the small model all predict this. Distinguishing them needs harder benign alerts, borderline cases, an adaptive attacker, and an operating-point comparison; it does not need malicious alerts the model already misses, which would only shrink the denominator of the quantity in question."),
  body("*Decoding asymmetry.* The small model ran at temperature 0 with a fixed seed; the frontier endpoint rejected both parameters. Cross-model differences therefore confound weights with decoding. Within-model comparisons are unaffected."),
  body("*One consumption path.* Section III-C models three ways an attacker string can reach the prompt. Only the parse path was run. The serialize and raw contrasts, and the per-item payload-residual diagnostics, were implemented but are not reported here."),
  body("*Prompt identity limits two comparisons.* Normalization and keyword filtering change the prompt on 30 and 15 of 288 items respectively, so B1N vs B1 and B2 vs B1 can show at most that much. This is a property of the payload corpus, most of which is plain ASCII, rather than a flaw in the conditions; a corpus weighted toward obfuscation would give those comparisons more to work with."),
  body("*Post hoc analysis, and what it does not isolate.* The provenance-note decomposition was designed after the main results and is reported as exploratory; its p-values are corrected within its own family of two. Its weakest level still labels fields ATTACKER-WRITABLE and shares P1's layout, so it bounds the cost of that bundle rather than of neutral provenance information. The neutral condition N isolates the label-and-framing change, and finds a large effect on gpt-4o-mini and no detected effect on gpt-6-astra; we did not test the difference between models, and no equivalence test supports a claim of zero effect anywhere. The residual cost of the neutral layout on the frontier model is not further decomposed: an inline rendering with neutral wording, which would separate the tier structure from the appendix relocation, was not run."),
  body("*Gate selection.* The gate is evaluated only on alerts the first stage proposed to close. On gpt-4o-mini every benign alert it saw was from the record-required stratum. The gate-alone condition G removes first-stage selection as an explanation on both models. It does not establish that the trusted fields sufficed for a safe close, and in two of three strata the design withholds the needed information by construction. We tested one gate prompt; a less conservative one is possible and untested."),
  body("*Payload authorship and adaptivity.* All 60 payloads were authored before the main experiment, with AI assistance (see Acknowledgment), with knowledge of the methods but without tuning against the results. The corpus was validated against the small model and may be weak against the frontier one for reasons unrelated to robustness. An adaptive attacker aware of the provenance framing would target it directly — most obviously with a minimal-claim payload that reads as an ordinary benign field value and asserts nothing. That case is untested."),
  body("*Prompt tuning asymmetry.* Baseline prompts follow [11] as closely as its description allows; the proposed conditions were written by us and iterated during piloting. The direction of the result makes this less of a concern than it would be for a positive finding, but it remains."),
  body("*Output-format constraint.* Every condition emits JSON for automated scoring, which narrows the contrast between the templated condition and its reference relative to prior work where baselines produced free text."),
  body("*Single-turn, non-agentic setting.* The model classifies one alert per call and does not query a SIEM or take actions. A deployed agent that correlates alerts has state that is itself part of the system under test."),
  body("*Model and time.* Results are a snapshot of specific model versions on specific dates, recorded with full identifiers in the artifacts."),
];

const conclusion = [
  H1("Conclusion"),
  body(`Telemetry-borne prompt injection follows from a structural fact: attackers write much of the text that security tooling reads. We examined two responses — marking provenance in the prompt, which does not interrupt information flow, and excluding untrusted input from a verification stage, which does so only there — and built an evaluation that attributes effects to components, pairs every comparison on the same alert, and measures the cost on benign traffic as a co-primary quantity. On the small model the marking reduced injected misses from ${pc(C4.B0_naive.injected_miss)}% to ${pc(C4.P1_pag_render.injected_miss)}% and raised over-escalation from ${pc(C4.B0_naive.oer)}% to ${pc(C4.P1_pag_render.oer)}%, with a clean-task Youden's J point estimate that fell from ${pp(C4.B0_naive.youden_j)} to ${pp(C4.P1_pag_render.youden_j)}; the exclusion reached zero misses by refusing every downgrade it was asked to verify, and every downgrade when asked about every alert; no advantage of relocating attacker text to an appendix over labeling it in place was demonstrated; and the same layout reworded neutrally lowered both the cost and the benefit to levels not distinguishable from the structured baseline. On a frontier model the corpus flipped no verdict, the prompts still cost, and the neutral rewording left the cost above the baseline. The pattern is consistent with the defenses moving the operating point rather than improving discrimination — we could not show the latter — and the cost appeared on both models we tested. We release the generator, the delivery-annotated corpus, the harness, and every per-item output, so that the question can be re-asked as models change — and so that the next answer is read on both axes.`, { noIndent: true }),
];

